sdl:
directive @cost(weight: String!) on ARGUMENT_DEFINITION | ENUM | FIELD_DEFINITION | INPUT_FIELD_DEFINITION | OBJECT | SCALAR
directive @listSize(
  assumedSize: Int
  slicingArguments: [String!]
  sizedFields: [String!]
  requireOneSlicingArgument: Boolean = true
) on FIELD_DEFINITION

input DefaultedNestedFilter {
  approx: Boolean = true @cost(weight: "-12")
}
input DefaultedFilter {
  nested: DefaultedNestedFilter = {} @cost(weight: "4")
}
type Query {
  search(filter: DefaultedFilter = {} @cost(weight: "15")): Int
    @cost(weight: "5")
}
